import json, time, urllib.request, boto3
def handler(event, context):
    reason = None
    if event['RequestType'] == 'Create':
        try:
            reason = check(event['ResourceProperties'])
        except Exception as e:
            reason = 'cdkpf probe could not run: %r' % e
    body = {'Status': 'FAILED' if reason else 'SUCCESS', 'Reason': (reason or 'ok')[:900],
            'PhysicalResourceId': event.get('PhysicalResourceId', context.log_stream_name),
            'StackId': event['StackId'], 'RequestId': event['RequestId'], 'LogicalResourceId': event['LogicalResourceId']}
    urllib.request.urlopen(urllib.request.Request(event['ResponseURL'], data=json.dumps(body).encode(), method='PUT', headers={'Content-Type': ''}))
def check(p):
    # Waits until the schedule starts a task or about 190 seconds pass; a new role takes a while to become assumable, so only an error that
    # persists is reported. The dead-letter message carries EventBridge's error.
    # The schedule fires every minute on its own; watch for about three runs.
    sqs, ecs = boto3.client('sqs'), boto3.client('ecs')
    deadline, last = time.time() + 190, 'no task started and nothing dead-lettered'
    while time.time() < deadline:
        for _ in range(1):
            tasks = ecs.list_tasks(cluster=p['Cluster'], desiredStatus='RUNNING')['taskArns'] + ecs.list_tasks(cluster=p['Cluster'], desiredStatus='STOPPED')['taskArns']
            if tasks:
                return task_outcome(ecs, p['Cluster'], tasks[0], deadline + 150)
            for m in sqs.receive_message(QueueUrl=p['Dlq'], MessageAttributeNames=['All'], WaitTimeSeconds=5).get('Messages', []):
                a = m.get('MessageAttributes', {})
                last = '%s: %s' % (a.get('ERROR_CODE', {}).get('StringValue'), a.get('ERROR_MESSAGE', {}).get('StringValue'))
                sqs.delete_message(QueueUrl=p['Dlq'], ReceiptHandle=m['ReceiptHandle'])
    return last
def task_outcome(ecs, cluster, arn, until):
    # A started task only counts when its container ran and exited 0.
    while True:
        t = ecs.describe_tasks(cluster=cluster, tasks=[arn])['tasks'][0]
        if t['lastStatus'] == 'STOPPED' or time.time() > until:
            break
        time.sleep(5)
    if t['lastStatus'] != 'STOPPED':
        ecs.stop_task(cluster=cluster, task=arn)
    c = t['containers'][0]
    if t['lastStatus'] == 'STOPPED' and c.get('exitCode') == 0:
        return None
    return 'task %s %s: %s / %s (exit %s, launchType %s)' % (arn.split('/')[-1], t['lastStatus'], t.get('stopCode'), t.get('stoppedReason'), c.get('exitCode'), t.get('launchType'))
